	vector3d up = GetPosition().Normalized();

	Frame *f = Frame::GetFrame(GetFrame());

	assert(f->GetBody()->IsType(ObjectType::PLANET));

	if (ManualDocking()) {
		if (!IsType(ObjectType::PLAYER)) {
